SELECT
,
d.name AS department_name
FROM
t_base_user e
LEFT JOIN t_dept d ON d.id = e.department_id

    e.is_valid=1 and d.is_valid=1


        AND e.phone like #{likephone}



        AND e.actual_name like #{likeActualName}



        AND (e.actual_name like #{likeName} or e.nick_name like #{likeName} or e.phone like #{likeName} or
        e.login_name like #{likeName})



        AND e.department_id = #{userQueryAo.departmentId}


        AND d.name = #{userQueryAo.deptName}


        AND e.approve_status = #{userQueryAo.approveStatus}


        AND e.id IN

            #{item}



order by e.create_time desc

SELECT
,
d.name AS department_name,
s.school_name,
s.school_code
FROM
t_base_user e
LEFT JOIN t_dept d ON d.id = e.department_id
LEFT JOIN t_school_manage s ON e.school_id = s.id
where e.is_valid=1


        AND e.phone like #{likephone}



        AND (e.actual_name like #{likeName} or e.nick_name like #{likeName} or e.phone like #{likeName} or
        e.login_name like #{likeName})



        AND e.department_id = #{userQueryAo.departmentId}


        AND d.name = #{userQueryAo.deptName}


        AND e.user_type = #{userQueryAo.userType}


        AND e.school_id = #{userQueryAo.schoolId}


        AND e.approve_status = #{userQueryAo.approveStatus}


        AND e.id IN

            #{item}


order by e.id desc

SELECT
FROM t_base_user e WHERE e.login_name = #{loginName} and e.login_pwd = #{loginPwd}
AND e.school_id = #{schoolId}
order by e.user_type asc

SELECT

FROM
t_base_user e
WHERE
e.actual_name = #{userName}
and e.phone = #{phone}
and e.school_id = #{schoolId}


    AND e.user_type = #{userType}

order by e.user_type asc
limit 1

SELECT

FROM
t_base_user e
WHERE
e.phone = #{phone} and e.is_valid = #{isValid}

    AND e.school_id = #{schoolId}

SELECT
FROM t_base_user e WHERE e.department_id = #{departmentId}
order by e.create_time desc

